def is_harshad(n):
    if n <= 0: return False
    temp = n
    s = 0
    while temp > 0:
        s += temp % 10
        temp //= 10
    return n % s == 0

def get_harshads_in_range(a, b):
    res = []
    for i in range(a, b + 1):
        if is_harshad(i):
            res.append(i)
    return res

