def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0: return False
    return True

def get_prime_frequency(path):
    freq = {}
    try:
        with open(path, 'r', encoding='utf-8') as f:
            content = f.read()
            tokens = content.split()
            for t in tokens:
                if t.isdigit():
                    num = int(t)
                    if is_prime(num):
                        freq[num] = freq.get(num, 0) + 1
    except FileNotFoundError:
        return {}
    return freq

